WITH TIPO_PESO_CORRETO AS (    SELECT V.CODPARC, TA.TIPO_PESO    FROM VINCULO_PARCEIRO_TIPO V JOIN TIPO_ARMAZENAGEM TA ON V.ID_TIPO_ARMAZENAGEM = TA.ID    WHERE V.CODPARC = :VAR_PARCEIRO_SELECIONADO    ORDER BY V.ID DESC LIMIT 1),MOVIMENTOS_UNIFICADOS AS (    SELECT G.DATA_ENTREGA AS DT_MOV, (CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN I.PESO_ITEM_LIQ ELSE I.PESO_ITEM END) AS PESO    FROM GESTAO_NOTAS_APROVACAO G    JOIN IMP_ITENS_NOTAS_APRV I ON G.NUNOTA = I.NUNOTA    JOIN TIPO_PESO_CORRETO TPC ON G.CODPARC = TPC.CODPARC    WHERE G.CODPARC = :VAR_PARCEIRO_SELECIONADO AND G.ENTREGUE = 1    UNION ALL    SELECT N.DTNEG AS DT_MOV, -(CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN N.PESO_ITEM_LIQ ELSE N.PESO_ITEM END) AS PESO    FROM IMP_NOTAS_ARMAZ N    JOIN TIPO_PESO_CORRETO TPC ON N.CODPARC = TPC.CODPARC    WHERE N.CODPARC = :VAR_PARCEIRO_SELECIONADO AND N.ATUALESTOQUE = 1)SELECT GREATEST(IFNULL(SUM(PESO), 0), 0) AS SALDO_INICIALFROM MOVIMENTOS_UNIFICADOSWHERE DT_MOV < :VAR_PERIODO_INICIO